export function normalizeDatabaseToolsMode(value) {
    if (value === false || value === "off")
        return "off";
    if (value === true || value === "write")
        return "write";
    return "read";
}
export function hasDatabaseReadTools(value) {
    return normalizeDatabaseToolsMode(value) !== "off";
}
export function hasDatabaseWriteTools(value) {
    return normalizeDatabaseToolsMode(value) === "write";
}
